INSERT INTO `5kcrm_customer_ledger_record` VALUES (1495, 728, 11, '对于原有的回传追溯使用记录，进行了调整回传触发限制\n缝皮保存（addqd → fengqian）仍会调 d()，但只有当前清点单 巡回 + 器械（洗手）主签已完成，且存在对应 PB 包 时才真正回传 CSSD。未签满时保存照常，只是不回传。\n\n按清点单回传，不再整台手术混传\nd() 改为按 OPERATIONID + id + types（msjor 主表 / vice 附表）筛选 apparatus_retrospec_addition 中的包，第 1 张、第 2 张清点单各自回传自己扫的包。\n\nPC 手动回传\n在追溯页 apparatusAddPackage.html 增加「回传CSSD」按钮，需确认后提交；接口为 cssd_upload，规则与自动回传一致（签满 + 本张单 PB 包）。', '', '已完成', 2, 1784194216);
