INSERT INTO `5kcrm_customer_ledger_record` VALUES (1719, 751, 11, '功能已经做完放到服务器上，暂未开启，明天汇报后根据情况开启功能，为落实弱口令排查与复杂口令管控要求，对本系统账号密码登录及个人中心修改密码功能进行了改造，规则如下：\n\n一、复杂度要求\n新密码须同时满足：长度不少于 8 位；包含大写字母、小写字母和数字。允许使用特殊字符，但不作强制要求。\n\n二、弱口令提示\n用户通过账号密码登录时，系统对当前密码进行复杂度校验。若不符合上述要求，登录仍可成功进入系统，但每次登录后会提示用户尽快到个人中心修改密码；不强制跳转、不阻断业务使用。统一认证（SSO）登录不进行该项提示。\n\n三、修改密码限制\n用户在个人中心修改密码时，新密码必须符合上述复杂度要求，否则修改失败并给出明确提示。旧密码校验逻辑保持不变。\n\n四、开关控制\n上述「登录弱口令提示」与「改密强制复杂度」均可通过后台统一开关启停，便于上线验证、临时关闭及正式启用，不影响正常登录与业务访问。', '处理中', '待发布', 2, 1785407149);
INSERT INTO `5kcrm_customer_ledger_record` VALUES (1720, 796, 79, '通过面板的工具箱中的 同步时间解决了时间快两分钟的问题，同步之后时间正常了，但是服务器卡了得有三分钟，建议不要经常点这个', '待处理', '已完成', 2, 1785408867);
